package vn.hust.restaurant.controller;import java.sql.*;import java.util.*;import vn.hust.restaurant.model.Customer;import vn.hust.restaurant.service.CustomerService;public class CustomerController{private final CustomerService s;public CustomerController(CustomerService s){this.s=s;}public List<Customer>list(String k)throws SQLException{return s.list(k);}public void save(Customer c)throws SQLException{s.save(c);}public void deactivate(int i)throws SQLException{s.deactivate(i);}}